package com.joysistvi.CyberAccess.service;
import com.joysistvi.CyberAccess.model.DrinkItem; import com.joysistvi.CyberAccess.repo.*; import java.sql.SQLException; import java.util.List;
public class DrinkServiceImpl { private final DrinkRepo repo; public DrinkServiceImpl(){this(new DrinkRepoImpl());} public DrinkServiceImpl(DrinkRepo r){repo=r;}
 public List<DrinkItem> getAll()throws SQLException{return repo.findAll();} public List<DrinkItem> getByCategory(int id)throws SQLException{return repo.findByCategory(Validation.id(id));} public DrinkItem getById(int id)throws SQLException{return repo.findById(Validation.id(id)).orElse(null);} public void add(DrinkItem x)throws SQLException{validate(x);repo.save(x);} public boolean update(DrinkItem x)throws SQLException{validate(x);Validation.id(x.getId());return repo.update(x);} public boolean delete(int id)throws SQLException{return repo.delete(Validation.id(id));} private void validate(DrinkItem x){if(x==null)throw new IllegalArgumentException("Drink is required.");x.setName(Validation.text(x.getName(),"Drink name",50));Validation.id(x.getCategoryId()); if(x.getPrice()==null || x.getPrice().signum()<0) throw new IllegalArgumentException("Drink price must be zero or greater.");}}
